// GENERATED by the gen:case stub (scripts/generate-case.ts; docs/PLAN.md 9.3, 13 M1). Do not edit.
// M2's generator must reproduce this file byte for byte (the FASTQ records the owner signs off
// in M1 are pinned). Source: the GRCh38 slice chr2:165,980,001-166,150,000 (Broad analysis set,
// MD5 of the bare uppercase sequence d0418b8e69260dafd2133fc10e22f977; case.md 3.7) and the
// haplotypes of case.md 3.2.
//
// Recipe, per fragment in CASE_FRAGMENTS order (index i from 0):
// - bases: the fragment's haplotype sequence, start..end 1-based closed, with only the listed SNP
//   sites changed from GRCh38; R1 and R2 are 150 bases: on a "+" fragment R1 is the first 150
//   bases and R2 the reverse complement of the last 150; on a "-" fragment they swap;
// - names (D-18): A00123:8:H7KJ2DSXY:<lane>:<tile>:<x>:<y>, lane 1 (the files are _L001_), with
//   comment <read>:N:0:<i7>+<i5> and an illustrative dual index per sample;
// - qualities: the 4-level NovaSeq 6000 alphabet (D-18; foundations.md 3.4). For each base a
//   mulberry32 stream seeded with 0x50303432 + 2i (R1) or + 2i + 1 (R2) gives r in [0, 1):
//   r < 0.86 -> F (Q37), r < 0.95 -> : (Q25), else , (Q11). # (Q2) is part of the alphabet but no
//   base here draws it.
// Library totals are metadata, not records: about 60 M pairs for the proband and the mother and
// about 32 M for the father (docs/PLAN.md 9.2; illustrative).

export interface CaseFastqRecord {
  /** The read id: the title's first word, without the @. It becomes the SAM QNAME. */
  id: string;
  /** The Illumina comment after the space: <read>:<is filtered>:<control>:<index>. */
  comment: string;
  sequence: string;
  quality: string;
}

export interface CaseFastqFile {
  /** Path in the case folder, as the capstone lists it (docs/PLAN.md 6.2). */
  path: string;
  sample: "P042-proband" | "P042-mother" | "P042-father";
  read: 1 | 2;
  records: readonly CaseFastqRecord[];
}

/** Where each read pair comes from, so a generator can rebuild it from the slice. */
export interface CaseFragment {
  sample: CaseFastqFile["sample"];
  /** The pair's read id. */
  id: string;
  chrom: "chr2";
  /** 1-based closed. */
  start: number;
  end: number;
  /** "+": R1 reads the fragment forward from start; "-": R1 reads back from end. */
  strand: "+" | "-";
  /** The haplotype the fragment was drawn from (case.md 3.2). */
  haplotype: "M1" | "M2" | "F1" | "F2";
  /** The case SNP the fragment covers, and the MANE exon it overlaps. */
  covers: "rs2298771" | "rs6432860";
  exon: number;
}

/** The 4-level quality alphabet: # , : F = Q2, Q11, Q25, Q37 (D-18). */
export const QUALITY_BINS = { "#": 2, ",": 11, ":": 25, F: 37 } as const;

