/** One record as its four FASTQ lines (no wrapping; a bare + line), each ending in a newline. */
export const fastqRecordText = (r: CaseFastqRecord): string =>
  `@${r.id} ${r.comment}\n${r.sequence}\n+\n${r.quality}\n`;

/** A file's decompressed text. */
export const fastqFileText = (file: CaseFastqFile): string => file.records.map(fastqRecordText).join("");
